starter.css:
body {
  color: #2c2016;
  background-color: #f7f1e3;
  font-family: 'Segoe UI', Arial, sans-serif;
  line-height: 1.5;
}

h1 {
  color: #5a3e2b;
  font-size: 40px;
  text-align: center;
}

h2 {
  color: #5a3e2b;
}

a {
  color: #e08a2e;
}

footer {
  background-color: #efe6d4;
}

table {
  background-color: white;
}

.hinweis {
  color: #b8860b;
  font-weight: bold;
}

#angebote, #oeffnungszeiten {
  color: #e08a2e;
}

nav a {
  color: #5a3e2b;
  text-decoration: none;
}

footer p {
  color: #5b6b7c;
}

.angebot {
  color: #1a9e5c;
  font-weight: bold;
}

th {
  text-align: left;
  color: #5a3e2b;
}

